rows = []

try:
	ds = system.db.runPrepQuery(
		"SELECT nombre FROM dbo.fa_cpk_program_specs WHERE linea = 'Auxiliar' ORDER BY nombre ASC",
		[],
		"papo_db"
	)

	for i in range(ds.rowCount):
		rows.append({
			"label": ds.getValueAt(i, "nombre"),
			"value": ds.getValueAt(i, "nombre")
		})

except Exception as e:
	system.util.getLogger("Andina.FA.CPK_FA.dropdownAuxiliar").error("Error loading referencias: " + str(e))

return rows
